// 1. Get raw inputs from previous nodes
const rawText = $('Gemini Vision Analysis').first().json.content.parts[0].text;
const distanceMeters = $('Calculate Distance via Google Maps').first().json.rows[0].elements[0].distance.value;
const durationText = $('Calculate Distance via Google Maps').first().json.rows[0].elements[0].duration.text;

// 2. Industry Standard Constants (South Africa)
const baseSurveyFee = 350; 
const costPerKm = 6.50;

// 3. Robust JSON Extraction (The "Regex" Fix)
// This finds the first '{' and last '}' and ignores everything outside them
const jsonRegex = /\{[\s\S]*\}/;
const match = rawText.match(jsonRegex);

if (!match) {
  throw new Error("Gemini failed to return a valid JSON object. Please check the image quality.");
}

const parsedData = JSON.parse(match[0]);

// 4. Calculations
const distanceKm = (Number(distanceMeters) / 1000).toFixed(2);
const totalSurveyFee = (baseSurveyFee + (parseFloat(distanceKm) * costPerKm)).toFixed(2);

// 5. Clean the Expert Advice text
// We pull ONLY the value from the JSON key, and fix any double-newlines
let expertAdvice = parsedData.consultant_note || "Our technician will assess the space on-site for a perfect fit.";
expertAdvice = expertAdvice.replace(/\\n/g, '\n'); 

// 6. Final Output Object for BotSailor
return [{
  json: {
    // These variables go to your WhatsApp message
    expert_advice: expertAdvice, 
    survey_fee: totalSurveyFee,
    distance_km: distanceKm,
    duration: durationText,

    // Metadata for your internal records
    system_type: parsedData.layout_type || "Shower Enclosure",
    frame_finish: parsedData.frame_finish || "Standard",
    compliance_note: "SANS 10400-N & 1263-1 Compliant",

    // Webhook data for routing
    customer_phone: $('Webhook Trigger').first().json.body.chat_id,
    checkout_url: `https://your-payment-link.com/pay?amount=${totalSurveyFee}&ref=${$('Webhook Trigger').first().json.body.chat_id}`
  }
}];

